#include <cstdint>
#include <vector>

struct State { int32_t x{ 0 }; int32_t y{ 0 }; int32_t health{ 100 }; int32_t stones{ 0 }; };

namespace
{
    void put(std::vector<uint8_t>& b, uint32_t v)
    {
        for (int i{ 0 }; i < 4; ++i) b.push_back(static_cast<uint8_t>(v >> (8 * i)));
    }
    uint32_t get(const std::vector<uint8_t>& b, std::size_t at)
    {
        uint32_t v{ 0 };
        for (int i{ 0 }; i < 4; ++i) v |= static_cast<uint32_t>(b[at + static_cast<std::size_t>(i)]) << (8 * i);
        return v;
    }
}

std::vector<uint8_t> saveState(const State& s)
{
    std::vector<uint8_t> b;
    put(b, 3);
    put(b, 16);
    put(b, static_cast<uint32_t>(s.x));
    put(b, static_cast<uint32_t>(s.y));
    put(b, static_cast<uint32_t>(s.health));
    put(b, static_cast<uint32_t>(s.stones));
    return b;
}

bool loadState(const std::vector<uint8_t>& bytes, State& out)
{
    if (bytes.size() < 8) return false;
    const uint32_t version{ get(bytes, 0) };
    const uint32_t size{ get(bytes, 4) };
    if (version < 1 || version > 3) return false;
    const uint32_t needed{ 4 + 4 * version };     // 8, 12, 16
    if (size != needed || bytes.size() - 8 < size) return false;
    State s;
    s.x = static_cast<int32_t>(get(bytes, 8));
    s.y = static_cast<int32_t>(get(bytes, 12));
    if (version >= 2) s.health = static_cast<int32_t>(get(bytes, 16));
    if (version >= 3) s.stones = static_cast<int32_t>(get(bytes, 20));
    out = s;
    return true;
}

unitTests:
std::vector<uint8_t> bytesOf(std::vector<uint32_t> words) { std::vector<uint8_t> b; for (uint32_t w : words) for (int i = 0; i < 4; ++i) b.push_back(static_cast<uint8_t>(w >> (8 * i))); return b; }
TEST("round trip") { State s; s.x = -5; s.y = 12; s.health = 40; s.stones = 7; State back; CHECK(loadState(saveState(s), back)); CHECK_EQ(back.x, -5); CHECK_EQ(back.y, 12); CHECK_EQ(back.health, 40); CHECK_EQ(back.stones, 7); }
TEST("the header") { const auto b = saveState(State{}); CHECK_EQ(b.size(), std::size_t{ 24 }); CHECK_EQ(int(b[0]), 3); CHECK_EQ(int(b[4]), 16); }
TEST("version 1 gets defaults") { State s; CHECK(loadState(bytesOf({ 1, 8, 3, 4 }), s)); CHECK_EQ(s.x, 3); CHECK_EQ(s.y, 4); CHECK_EQ(s.health, 100); CHECK_EQ(s.stones, 0); }
TEST("version 2") { State s; CHECK(loadState(bytesOf({ 2, 12, 1, 2, 55 }), s)); CHECK_EQ(s.health, 55); CHECK_EQ(s.stones, 0); }
TEST("newer version") { State s; s.x = 99; CHECK(!loadState(bytesOf({ 4, 20, 1, 2, 3, 4, 5 }), s)); CHECK_EQ(s.x, 99); }
TEST("broken data") { State s; s.x = 99; CHECK(!loadState({}, s)); CHECK(!loadState(bytesOf({ 3 }), s)); CHECK(!loadState(bytesOf({ 3, 16, 1, 2 }), s)); CHECK(!loadState(bytesOf({ 2, 8, 1, 2 }), s)); CHECK(!loadState(bytesOf({ 0, 0 }), s)); CHECK_EQ(s.x, 99); }

